// Render the approver's reason form. The Wait node resumes on GET (same as the Slack/email
// approve link), so submit GET and carry signature + decision as hidden inputs - a GET submit
// rewrites the query string, so anything not a field would be lost.
const q = $json.query || {};
const resume = q.resume || '';
const rid = q.rid || '';
const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
let base = resume; const params = [];
const qi = resume.indexOf('?');
if (qi >= 0) {
  base = resume.slice(0, qi);
  resume.slice(qi + 1).split('&').forEach(kv => {
    if (!kv) return;
    const i = kv.indexOf('=');
    const k = i < 0 ? kv : kv.slice(0, i);
    const v = i < 0 ? '' : kv.slice(i + 1);
    params.push([decodeURIComponent(k), decodeURIComponent(v)]);
  });
}
const hidden = params.map(([k, v]) => `<input type="hidden" name="${esc(k)}" value="${esc(v)}">`).join('');
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>Reject ${esc(rid)}</title>
<style>body{font-family:system-ui,-apple-system,'Segoe UI',sans-serif;background:#0f1115;color:#e6e8ec;display:flex;min-height:100vh;align-items:center;justify-content:center;margin:0}
.card{background:#171a21;border:1px solid #262b36;border-radius:12px;padding:28px 30px;max-width:460px;width:100%;box-sizing:border-box}
h1{font-size:18px;margin:0 0 6px}p{color:#9aa3b2;font-size:13px;margin:0 0 16px;line-height:1.5}
label{display:block;font-size:13px;margin:0 0 6px;color:#c7cdd8}
textarea{width:100%;box-sizing:border-box;min-height:96px;background:#0f1115;border:1px solid #2c323e;border-radius:8px;color:#e6e8ec;padding:10px;font:inherit;resize:vertical}
button{margin-top:14px;width:100%;background:#e5484d;color:#fff;border:0;border-radius:8px;padding:11px;font-size:14px;font-weight:600;cursor:pointer}</style></head>
<body><form class="card" method="GET" action="${esc(base)}">${hidden}
<h1>Reject ${esc(rid)}</h1>
<p>The reason goes back to the requester so they can revise and resubmit. It is written to the audit log.</p>
<label for="reason">Reason for rejection</label>
<textarea id="reason" name="reason" required placeholder="e.g. Over budget for this cost center. Re-scope or split the order."></textarea>
<button type="submit">Reject and return to requester</button></form></body></html>`;
return [{ json: { html } }];

// Bound the loop and build the prefilled revision link. Chain root = original request_id.
const b = $json.body || $json;
const now = new Date().toISOString();
const MAX = 3;
const count = Number(b.revision_count) || 0;
const chain = b.revision_of || b.request_id;
const is_final = count >= MAX;
const next_count = count + 1;
// URLSearchParams is not in the Code sandbox; build the query string by hand.
const enc = encodeURIComponent;
const fields = {
  business_unit: b.business_unit || '', sku: b.sku || '', item_description: b.item_description || '',
  quantity: (b.quantity != null ? b.quantity : ''), category: b.category || '',
  cost_center: b.cost_center || '', preferred_vendor: b.preferred_vendor || '',
  justification: b.justification || '', requester_email: b.requester_email || '',
  revision_of: chain, revision_count: next_count,
};
const qp = Object.keys(fields).map(k => enc(k) + '=' + enc(String(fields[k]))).join('&');
const revise_link = 'https://your-n8n.example/form/fde-procurement-request-dev' + '?' + qp;
return [{ json: { ...b, now, MAX, count, next_count, chain, is_final, revise_link } }];

const j = $json;
return [{ json: {
  request_id: j.request_id, event: 'REJECTED_FINAL',
  detail: JSON.stringify({ reason: j.reject_reason || '', revisions: j.count, cap: j.MAX }),
  actor: j.requester_email || 'system', ts: j.now,
  submitted_at: null, decided_at: j.now, cycle_seconds: null,
  revision_of: j.chain, revision_count: j.count,
}}];

const j = $json;
return [{ json: {
  request_id: j.request_id, event: 'REVISION_REQUESTED',
  detail: JSON.stringify({ reason: j.reject_reason || '', attempt: j.next_count, link: j.revise_link }),
  actor: j.requester_email || 'system', ts: j.now,
  submitted_at: null, decided_at: null, cycle_seconds: null,
  revision_of: j.chain, revision_count: j.next_count,
}}];
